// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(uint256 v1, uint256 v2, address actor) public {
        vm.assume(actor != address(this));
        c.SetMinSum(v1);
        c.Initialized();
        // After initialization, SetMinSum must never take effect.
        vm.prank(actor);
        try c.SetMinSum(v2) {
            // call completed on the buggy path
        } catch {
            // reference path: call reverts
        }
        assertTrue(c.MinSum() == v1);
    }
}
